    return output

def remove_extras(lst):
    new_list=[]
    for i in range(len(lst)):
        if lst[i] in lst[:i]:
            new_list = new_list
        else:
            new_list = new_list + [lst[i]]
    return new_list

def remove_extras(lst):
    keep = []
    for i in lst :
        if i not in keep :
            keep.append(i)
    return keep

def remove_extras(lst):
    new = []
    x = 0
    for x in range(len(lst)):
        if lst[x] not in new:
            new += [lst[x]]
    return new

def remove_extras(lst):
    a=[]
    for i in lst:
        if i not in a:
